import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import {
  api, apiUrl, driveDirectUrl,
  ENDPOINTS, isMockApi, mockGetProductImages, atyabLog
} from "../api.js";

/* ============================================================
   أطياب الجاسم — شريحة الصور (imagesSlice)

   الصور تُجلب من End Point بالـ productId وتُخزَّن هنا مفهرسة به:
     · main[productId]      الصورة الأساسية (للبطاقات والقوائم)
     · galleries[productId] صور المنتج الأربع (لصفحة المنتج)

   ★ الرأي المُعتمد: الصورة الأساسية تأتي داخل المنتج نفسه
     (Drive URL من الـ API) فتظهر الشبكة فوراً بلا طلبات إضافية،
     وصور المعرض الأربع تُجلب عند فتح صفحة المنتج فقط (توفيراً
     للنطاق). والـ View يحمل mainImgUrl جاهزاً — أسهل للكارت.
   ★ روابط Google Drive تُحوَّل تلقائياً إلى روابط عرض مباشرة
     (driveDirectUrl) قبل التخزين والعرض.
   ★ شرط التنفيذ: الصورة المخزَّنة لا تُجلب مجدداً أبداً.
   ============================================================ */

async function fetchGalleryUrls(productId) {
  const id = Number(productId) || 0;
  if (isMockApi()) return mockGetProductImages(id);
  const res = await api.get(apiUrl(ENDPOINTS.productGallery(id)));
  const list = Array.isArray(res.data) ? res.data : [];
  function rank(r) {
    const n = String((r && r.imageName) || "").toLowerCase();
    if (n.indexOf("second") !== -1 || n === "2") return 2;
    if (n.indexOf("third") !== -1 || n === "3") return 3;
    if (n.indexOf("fourth") !== -1 || n === "4") return 4;
    return 9;
  }
  return list
    .slice()
    .sort(function (a, b) { return rank(a) - rank(b) || (Number(a.imageId) || 0) - (Number(b.imageId) || 0); })
    .map(function (r) { return driveDirectUrl(r && (r.imageUrl || r.url || r.src)); })
    .filter(Boolean);
}

const initialState = {
  main: {},
  galleries: {},
  status: "idle",
  error: null
};

/* صور المعرض الأربع لصفحة المنتج */
const galleryInflight = {};
export const getProductImages = createAsyncThunk(
  "images/getProductImages",
  async function (productId, { rejectWithValue }) {
    const id = Number(productId) || 0;
    try {
      atyabLog("gallery FETCH", id);
      const urls = await fetchGalleryUrls(id);
      delete galleryInflight[id];
      atyabLog("gallery CACHED", id, (urls || []).length);
      return { productId: id, urls: urls };
    } catch (err) {
      delete galleryInflight[id];
      atyabLog("gallery FAIL", id);
      return rejectWithValue("تعذّر جلب صور المنتج");
    }
  },
  {
    condition: function (productId, { getState }) {
      const id = Number(productId) || 0;
      const images = getState().images;
      if (!images) return true;
      if (images.galleries && Object.prototype.hasOwnProperty.call(images.galleries, id)) { atyabLog("gallery CACHE-HIT", id); return false; }
      if (galleryInflight[id]) { atyabLog("gallery IN-FLIGHT", id); return false; }
      galleryInflight[id] = true;
      atyabLog("gallery MISS", id);
      return true;
    }
  }
);

const imagesSlice = createSlice({
  name: "images",
  initialState: initialState,
  reducers: {},
  extraReducers: function (builder) {
    builder
      .addCase(getProductImages.fulfilled, function (state, action) {
        state.status = "succeeded";
        state.galleries[action.payload.productId] = action.payload.urls;
      })
      .addCase(getProductImages.rejected, function (state, action) {
        state.status = "succeeded";
        if (!Object.prototype.hasOwnProperty.call(state.galleries, action.meta.arg)) state.galleries[action.meta.arg] = [];
      });
  }
});

/* ---------- مُنتقيات ---------- */
export function selectMainImage(state, productId) {
  return (state.images && state.images.main[Number(productId)]) || null;
}

export function selectMainImagesMap(state) {
  return (state.images && state.images.main) || {};
}

export function selectProductGallery(state, productId) {
  return (state.images && state.images.galleries[Number(productId)]) || null;
}

export default imagesSlice.reducer;
