/* علم كل عملة صار في src/constants/currencyFlags.js — ملف ثوابت لا مكوّنات */

/* أيقونة عامة */
export function Icon(props) {
  const name = props.name;
  const cls = props.className;
  const body = ICONS[name] != null ? ICONS[name] : ICONS.dot;
  const extra = props.viewBox ? { viewBox: props.viewBox } : { viewBox: "0 0 24 24" };
  return (
    <svg
      className={cls}
      viewBox={extra.viewBox}
      fill={props.fill || "none"}
      stroke={props.fill ? "none" : "currentColor"}
      strokeWidth={props.strokeWidth || 1.7}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
}

/* علم دولة */
export function Flag(props) {
  const code = FLAGS[props.code] ? props.code : "sa";
  return (
    <svg
      className={props.className}
      viewBox="0 0 24 16"
      preserveAspectRatio="none"
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: FLAGS[code] }}
    />
  );
}

