/* صورة بديلة (مجسم SVG) — تُعرض داخل حاوية .pd-mock */
export function Mock(props) {
  return (
    <div className={"pd-mock" + (props.className ? " " + props.className : "")} role="img" aria-label={props.label || ""}>
      <svg
        viewBox="0 0 120 150"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        dangerouslySetInnerHTML={{ __html: MOCKS[props.name] || MOCKS.bottle }}
      />
      {props.caption ? <span className="pd-mock-cap">{props.caption}</span> : null}
      {props.note ? <span className="pd-mock-note">{props.note}</span> : null}
    </div>
  );
}

