/* ============================================================
   أطياب الجاسم (React) — الصفحة الرئيسية (MainPage)

   كل ما في الصفحة الرئيسية من نصّ وتصميم: قسم الهيرو (مع الكلمات
   المتغيّرة والإحصاءات)، وقسما العطور والبخور (العمود النصّي فقط:
   العنوان + الوصف + المزايا + الزر)، وشريط العبارات المتحرّك، وقسم
   آراء العملاء.

   ★ الصفحة تستدعي ما تحتاجه هي فقط (كما في المشروع المرجعي): تُنادي
     أنيميشنات الصفحة الرئيسية الثلاثة بنفسها — لا تصل كـprops من App:
        <LogoAnimation />   كرة الشعار
        <PerfumeView2D />   عرض العطور ثنائي الأبعاد
        <Bakhour3D />       مشهد المبخرة ثلاثي الأبعاد
     ولا شيء آخر خارجها: الهيدر والفوتر في التخطيط العام (MainLayout).
   ★ كل الأنماط محصورة بـ#homeView في Main.css، لذلك الجذر هنا يحمل
     id="homeView" — بلا استثناء.
   ★ مسار الصفحة: "/" — تُعلن اسمها بـusePageMeta (عنوان التبويب + data-route).
   ============================================================ */

import { useEffect, useState } from "react";
import { HomeSkeleton } from "../components/Skeletons/index.js";
import { Link } from "react-router-dom";
import { PATHS } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { useAppSelector, useAppDispatch } from "../redux/hooks.js";
import { getServerReviews, selectServerComments, reviewsActions, STORE_KEY_HOME } from "../redux/slices/reviewsSlice.js";
import UserComment from "../components/UserExperience/UserComment.jsx";
import { Icon } from "../components/Source/Icons.jsx";
import LogoAnimation from "../components/ProductAnimation/LogoAnimation.jsx";
import PerfumeView2D from "../components/ProductAnimation/2DPerfumeView.jsx";
import Bakhour3D from "../components/ProductAnimation/3DBakhour.jsx";

const ROTATOR_WORDS = [
  "لبيع العطور الفاخرة",
  "للعطور الشرقية الأصيلة",
  "للبخور والعود الفاخر",
  "لعبقٍ يبقى في الذاكرة"
];

const MARQUEE = [
  "عطور شرقية أصيلة",
  "عود معتّق فاخر",
  "مسك وعبق الجزيرة",
  "بخور معمّر بيد خبير",
  "تغليف هدايا فاخر",
  "توصيل لكل الإمارات",
  "ضمان الأصالة 100%",
  "تصميم عطور حسب ذوقك",
  "زيوت مركّزة عالية النقاء",
  "خدمة عملاء على مدار الساعة"
];

/* آراء العملاء — تُملأ حياً من /api/reviews (أفضل 20)، والثابت احتياط فقط */
const FALLBACK_TESTIMONIALS = [];

const PERFUME_FEATURES = [
  { icon: "flask", title: "جودة العطور", text: "زيوت عطرية مركّزة عالية النقاء تُمنح ثباتاً وفوحاناً يتجاوز العطر التجاري." },
  { icon: "spark", title: "دقّة التصنيع", text: "مزج متوازن ومراحل تعتيق مضبوطة تُخرِج النوتات العليا والوسطى والقاعدية بانسجام." },
  { icon: "oud", title: "تنوّع الخيارات", text: "تشكيلة واسعة: شرقي، مسك، عود، زهري ومنعش — ولكل ذوقٍ نصيب." }
];

const INCENSE_FEATURES = [
  { icon: "flame", title: "جودة البخور", text: "خشب وعود مقطّف من مصادر موثوقة، بلا إضافات رخيصة تُفسد العبق." },
  { icon: "clock", title: "مدة الفخامة", text: "تركيز عالٍ يمنح تعتيقاً وبقاءً طويلاً على الملابس والمجالس." },
  { icon: "oud", title: "تنوّع الأنواع", text: "معمّر، مشلول، معمول، ومكسّرات — بمقاسات تناسب كل مناسبة." },
  { icon: "gift", title: "تصميم حسب ذوقك", text: "خلطات وبخور مخصّص باسمك أو لمناسبتك، بتغليفٍ فاخرٍ يليق بالإهداء." }
];

function ArrowIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M19 12H5" />
      <path d="m12 19-7-7 7-7" />
    </svg>
  );
}

function DropIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.6} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 2.5c1.4 4.6 5.2 6 5.2 10.6A5.2 5.2 0 0 1 12 18.3a5.2 5.2 0 0 1-5.2-5.2C6.8 8.5 10.6 7.1 12 2.5Z" />
    </svg>
  );
}

/* الكلمة المتغيّرة في عنوان الهيرو — تتبدّل كل ٣.٦ ثانية كما في الأصل */
function HeroRotator() {
  const [at, setAt] = useState(0);
  useEffect(
    function () {
      const id = window.setInterval(function () {
        setAt(function (prev) {
          return (prev + 1) % ROTATOR_WORDS.length;
        });
      }, 3600);
      return function () {
        window.clearInterval(id);
      };
    },
    []
  );
  return (
    <span className="hero-rotator" id="heroRotator">
      {ROTATOR_WORDS.map(function (word, i) {
        return (
          <span className={"rot-word" + (i === at ? " active" : "")} key={word}>
            {word}
          </span>
        );
      })}
    </span>
  );
}

function FeatureList(props) {
  return (
    <ul className="feature-list">
      {props.items.map(function (item) {
        return (
          <li key={item.title}>
            <span className="fi">
              <Icon name={item.icon} strokeWidth={1.7} />
            </span>
            <div>
              <b>{item.title}</b>
              <span>{item.text}</span>
            </div>
          </li>
        );
      })}
    </ul>
  );
}

export default function MainPage(props) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  /* الصفحة تعلن اسمها وعنوان تبويبها بنفسها. `active` تأتي من التخطيط
     العام: الرئيسية تبقى مُركَّبة دائماً وتُخفى بـ[hidden]، فلا تكتب
     data-route/عنوان التبويب وهي مخفيّة، وتُعيدهما عند العودة إليها. */
  const active = !props || props.active !== false;
  usePageMeta({ route: "home", active: active });
  /* ★ آراء الرئيسية حياً من /api/reviews (أفضل 20) — تُجلب مرة واحدة */
  const dispatch = useAppDispatch();
  useEffect(
    function () {
      const thunk = getServerReviews(STORE_KEY_HOME);
      if (thunk) dispatch(thunk);
    },
    [dispatch]
  );
  const serverReviews = useAppSelector(function (s) {
    return selectServerComments(s, STORE_KEY_HOME);
  });
  const testimonials = serverReviews.length
    ? serverReviews
    : FALLBACK_TESTIMONIALS.map(function (r, i) {
        return { id: "fb-" + i, name: r.n, nameEn: r.nEn, rating: r.s, date: r.c, verified: false, helpful: 0, text: r.t, reply: "" };
      });
  const [helpfulIds, setHelpfulIds] = useState([]);
  function onHelpful(id) {
    dispatch(reviewsActions.markHelpful({ key: STORE_KEY_HOME, id: id }));
    setHelpfulIds(function (prev) {
      return prev.indexOf(id) === -1 ? prev.concat([id]) : prev;
    });
  }
  /* سكيلتون أول رسم فقط (يهيّئ العين قبل اكتمال المشاهد الثقيلة) */
  const [ready, setReady] = useState(false);
  useEffect(function () {
    const id = window.requestAnimationFrame(function () {
      setReady(true);
    });
    return function () {
      window.cancelAnimationFrame(id);
    };
  }, []);

  if (!ready) {
    return (
      <section className="view hm" id="homeView">
        <div className="container">
          <HomeSkeleton />
        </div>
      </section>
    );
  }

  return (
    <section className="view hm" id="homeView">
      {/* ============ 1 · Hero ============ */}
      <section id="homeHero" className="section hero" data-river="1">
        <div className="container hero-grid">
          <div className="hero-copy">
            <span className="eyebrow">من الإمارات وإلى العالم</span>
            <h1>
              متجر أطياب الجاسم
              <br />
              <HeroRotator />
            </h1>
            <p className="hero-lead">
              من قلب الجزيرة العربية نقدّم لك عطوراً وبخوراً مركّبة بعناية من أجود المواد الخام، بتوقيعٍ شرقيٍّ يفوح فخامةً
              وأصالة. رحلة عبق تبدأ من أيدينا وتصل إلى بيتك.
            </p>
            <div className="hero-actions">
              <Link className="btn-primary" to={PATHS.register}>
                سجل الآن
                <ArrowIcon />
              </Link>
              <Link className="btn-ghost" to={PATHS.incense}>
                شاهد البخور
              </Link>
            </div>
            <ul className="hero-stats">
              <li>
                <b>+120</b>
                <span>عطر وبخور</span>
              </li>
              <li>
                <b>100%</b>
                <span>أصالة مضمونة</span>
              </li>
              <li>
                <b>24 س</b>
                <span>توصيل سريع</span>
              </li>
            </ul>
          </div>

          <LogoAnimation active={active} />
        </div>
      </section>

      {/* ============ 2 · العطور ============ */}
      <section id="homePerfumes" className="section showcase" data-river="1">
        <div className="container showcase-grid">
          <PerfumeView2D active={active} />

          <div className="copy">
            <span className="eyebrow">عطورنا</span>
            <h2>
              عبقٌ يُصنع <span className="gold-text">بدقّة</span> من أول قطرة
            </h2>
            <p className="lead">
              كل عطر لدينا يُركّب على مراحل، من انتقاء المادة الخام حتى تعتيق الخلطة، ليصل إليك بهويةٍ شرقية مميّزة
              وثباتٍ يبقى معك طوال اليوم.
            </p>
            <FeatureList items={PERFUME_FEATURES} />
            <Link className="btn-primary" to={PATHS.perfumes}>
              تصفّح تشكيلتنا
              <ArrowIcon />
            </Link>
          </div>
        </div>
      </section>

      {/* ============ 3 · البخور ============ */}
      <section id="homeIncense" className="section showcase showcase-incense" data-river="1">
        <div className="container showcase-grid showcase-grid--incense">
          <Bakhour3D active={active} />

          <div className="copy">
            <span className="eyebrow">بخورنا</span>
            <h2>
              بخورٌ يعتّق <span className="gold-text">الفخامة</span> في مجلسك
            </h2>
            <p className="lead">
              اخترنا لك أفخر أنواع البخور والعود، معمّرة بأيدٍ خبيرة على نارٍ هادئة، لتجلس في مجلسك وعبقٌ يبقى ساعاتٍ بعد
              مغادرة الضيف.
            </p>
            <FeatureList items={INCENSE_FEATURES} />
            <Link className="btn-primary" to={PATHS.incense}>
              اطلب بخوراً مخصّصاً
              <ArrowIcon />
            </Link>
          </div>
        </div>
      </section>

      {/* ============ 4 · العبارات المتحرّكة ============ */}
      <section id="homeBadges" className="section badges" data-river="1">
        <div className="container">
          <div className="marquee">
            <div className="marquee-track">
              {MARQUEE.concat(MARQUEE).map(function (phrase, i) {
                return (
                  <span className="phrase" key={i}>
                    <DropIcon />
                    {phrase}
                  </span>
                );
              })}
            </div>
          </div>
        </div>
      </section>

      {/* ============ 5 · آراء العملاء ============ */}
      <section id="homeTestimonials" className="section testimonials" data-river="1">
        <div className="container">
          <div className="section-head">
            <span className="eyebrow" style={{ justifyContent: "center" }}>
              آراء عملائنا
            </span>
            <h2>
              شهاداتٌ من قلب <span className="gold-text">تجربتهم</span>
            </h2>
            <p>تقييمات حقيقية من عملائنا حول العطر والبخور والتغليف والتوصيل.</p>
          </div>
          {testimonials.length > 2 ? (
            <div className="t-marquee" dir="ltr">
              <div className="t-marquee-track">
                {[0, 1].map(function (copy) {
                  return (
                    <ul className="t-marquee-half" dir="rtl" key={copy} aria-hidden={copy === 1 ? "true" : undefined}>
                      {testimonials.map(function (c) {
                        return (
                          <UserComment
                            key={String(c.id) + "-" + copy}
                            comment={c}
                            lang={language}
                            helpfulOn={helpfulIds.indexOf(c.id) !== -1}
                            onHelpful={onHelpful}
                          />
                        );
                      })}
                    </ul>
                  );
                })}
              </div>
            </div>
          ) : (
            <ul className="t-static" dir="rtl">
              {testimonials.map(function (c) {
                return (
                  <UserComment
                    key={String(c.id)}
                    comment={c}
                    lang={language}
                    helpfulOn={helpfulIds.indexOf(c.id) !== -1}
                    onHelpful={onHelpful}
                  />
                );
              })}
            </ul>
          )}
        </div>
      </section>
    </section>
  );
}
