/* ============================================================
   أطياب الجاسم (React) — المسارات (routes.js)

   مصدر واحد لكل مسار في الموقع، تماماً كما أنّ كل صفحة في المشروع
   المرجعي لها مسار واحد في <Routes>:
     · PATHS      ثوابت المسارات (تُستعمل في Link/navigate)
     · productPath(id) · maintenancePath(key)
     · pathOf()   يحوّل أي وجهة قديمة ("#perfumes" · "product/5" ·
                  "#/perfumes") إلى مسار راوتر ("/perfumes" · "/product/5")
                  حتى تبقى وجهات ملف البيانات (ATYAB_PAGES) تعمل كما هي.
   ★ كل تنقّل في الموقع يمرّ من راوتر react-router-dom — لا مكان آخر
     يقرأ location.hash أو يكتبه.
   ============================================================ */

export const PATHS = {
  home: "/",
  perfumes: "/perfumes",
  incense: "/incense",
  ouds: "/ouds",
  product: "/product",
  offers: "/offers",
  cart: "/cart",
  checkout: "/checkout",
  wishlist: "/wishlist",
  profile: "/profile",
  contact: "/contact",
  search: "/search",
  about: "/about",
  shipping: "/shipping",
  branches: "/branches",
  payments: "/payments",
  legal: "/legal",
  login: "/login",
  register: "/register",
  paymentReturn: "/payment/return",
  paymentStart: "/payment/start",
  maintenance: "/maintenance"
};

/* مسار صفحة منتج: /product/5 */
export function productPath(id) {
  return PATHS.product + "/" + Number(id);
}

/* مسار صفحة الصيانة لصفحة غير جاهزة: /maintenance/collections */
export function maintenancePath(key) {
  return key ? PATHS.maintenance + "/" + encodeURIComponent(key) : PATHS.maintenance;
}

/* أي وجهة قديمة → مسار راوتر */
export function pathOf(value) {
  let path = String(value == null ? "" : value).trim();
  if (!path || path === "#" || path === "#/") return PATHS.home;
  path = path.replace(/^#/, "");
  if (path === "edit" || path.indexOf("edit/") === 0) return PATHS.perfumes;
  if (path.charAt(0) !== "/") path = "/" + path;
  return path;
}

/* نفس المسار بصيغة href — لروابط <a> العادية داخل HashRouter */
export function hrefOf(value) {
  return "#" + pathOf(value);
}

/* وجهة صفحة معروفة من ATYAB_PAGES (label/target) */
export function pathForPage(key, pages) {
  const entry = pages && pages[key];
  return entry && entry.target ? pathOf(entry.target) : maintenancePath(key);
}
