/* ============================================================
   أطياب الجاسم (React) — الشاشة المنبثقة لقصة المنتج (StoryModal)

   نافذة «اعرف قصته» كما في الموقع: الصورة التوضيحية + اسم المجموعة +
   اسم المنتج + شارة النوع والحجم + نص القصة + الهرم العطري/طبقات الخلطة
   + وقائع المنتج (التقييم · عدد المقيّمين · الكمية المتبقية · توفيرك)
   + سطر الختام.

   ★ مصدر الحقيقة: `ui.storyProductId` في Redux — زر «اعرف قصته»
     في ProductDetails يُطلقه بـ uiActions.openStory(id)، وهذه النافذة
     تقرأ المعرّف وتجلب المنتج من البيانات. الإغلاق (خلفية/×/Escape)
     يمرّ عبر uiActions.closeStory.
   ============================================================ */

import { useEffect, useMemo } from "react";
import { ATYAB_byId, ATYAB_catalogOf } from "../../data/products.js";
import { productName, productSize, productStory, productNotes, genderLabelOf, tr2 } from "../../i18n.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { Money } from "../Source/Money.jsx";
import { Icon, ProductImage } from "../Source/Icons.jsx";
import { selectProductProfile } from "../../redux/slices/productProfilesSlice.js";
import { selectProductGallery } from "../../redux/slices/imagesSlice.js";

function badgeOf(p, language) {
  const isBakhoor = !!p.kindLabel;
  const label = isBakhoor
    ? language === "en"
      ? p.kind === "oud"
        ? "Oud"
        : "Bakhoor"
      : p.kindLabel
    : genderLabelOf(p.gender, language);
  const icon = isBakhoor
    ? p.kind === "oud"
      ? "oud"
      : p.kind === "tablets"
      ? "tablet"
      : p.kind === "gift"
      ? "gift"
      : p.kind === "mabkhara"
      ? "burner"
      : "flame"
    : p.gender === "men"
    ? "men"
    : p.gender === "women"
    ? "women"
    : "unisex";
  return { label: label, icon: icon, isBakhoor: isBakhoor };
}

export default function StoryModal() {
  const dispatch = useAppDispatch();
  const id = useAppSelector(function (s) {
    return s.ui.storyProductId;
  });
  const product = id ? ATYAB_byId(Number(id)) : null;
  const language = useAppSelector(function (s) { return s.ui.language; });
  const profile = useAppSelector(function (s) { return selectProductProfile(s, Number(id)); });
  const gallery = useAppSelector(function (s) { return selectProductGallery(s, Number(id)); });

  /* إغلاق بمفتاح Escape */
  useEffect(
    function () {
      if (!product) return undefined;
      function onKey(e) {
        if (e.key === "Escape") dispatch(uiActions.closeStory());
      }
      document.addEventListener("keydown", onKey);
      return function () {
        document.removeEventListener("keydown", onKey);
      };
    },
    [product, dispatch]
  );

  const storyText = profile
    ? (language === "en" ? (profile.storyEn || profile.story || "") : (profile.story || profile.storyEn || ""))
    : productStory(product, language);
  const notes = useMemo(
    function () {
      if (profile && (profile.top || profile.heart || profile.base)) {
        const rows = language === "en"
          ? [["Top", profile.topEn || profile.top], ["Heart", profile.heartEn || profile.heart], ["Base", profile.baseEn || profile.base]]
          : [["المقدمة", profile.top], ["القلب", profile.heart], ["القاعدة", profile.base]];
        return rows.filter(function (row) { return !!row[1]; });
      }
      if (!product) return [];
      const n = productNotes(product, language);
      return [
        [tr2(language, "Top", "المقدمة"), n.top],
        [tr2(language, "Heart", "القلب"), n.heart],
        [tr2(language, "Base", "القاعدة"), n.base]
      ].filter(function (row) {
        return !!row[1];
      });
    },
    [product, profile, language]
  );

  if (!product) return null;

  const cat = ATYAB_catalogOf ? ATYAB_catalogOf(product.id) : null;
  const badge = badgeOf(product, language);
  const saved = Math.max(0, (product.oldPrice || 0) - product.price);
  const name = productName(product, language);
  const size = productSize(product, language);

  function close() {
    dispatch(uiActions.closeStory());
  }

  return (
    <div className="screen is-open" role="dialog" aria-modal="true" aria-labelledby="storyTitle">
      <div className="screen-backdrop" onClick={close} />

      <div className="screen-panel story-panel">
        <div className="screen-head">
          <h2 id="storyTitle">{badge.isBakhoor ? "قصة البخور" : "قصة العطر"}</h2>
          <button className="screen-close" type="button" aria-label="إغلاق" onClick={close}>
            <Icon name="x" strokeWidth={2} />
          </button>
        </div>

        <div className="screen-body story-body">
          <div className="story-hero">
            <div className="story-art">
              {product.image || (gallery && gallery[0]) ? (
                <ProductImage product={product} src={product.image || gallery[0]} alt={product.name} eager />
              ) : (
                <div className="img-skeleton" aria-hidden="true" />
              )}
            </div>
            <div className="story-head">
              <span className="pd-crumb">{tr2(language, (cat && cat.collectionFallbackEn) || "Our perfumes", (cat && cat.collectionFallback) || "عطورنا")}</span>
              <h3>{name}</h3>
              <div className="story-tags">
                <span className={"pd-gender" + (badge.isBakhoor ? " pd-kind" : "")}>
                  <i aria-hidden="true">
                    <Icon name={badge.icon} />
                  </i>
                  {badge.label}
                </span>
                <span className="pd-size">{size}</span>
              </div>
            </div>
          </div>

          <p className="story-text">{storyText}</p>

          {notes.length ? (
            <div className="story-notes">
              <h4>{(cat && cat.notesTitle) || "الهرم العطري"}</h4>
              {notes.map(function (row) {
                return (
                  <div className="story-note" key={row[0]}>
                    <span className="story-note-k">{row[0]}</span>
                    <span className="story-note-v">{row[1]}</span>
                  </div>
                );
              })}
            </div>
          ) : null}

          <div className="story-facts">
            <div className="story-fact">
              <span>التقييم</span>
              <b>{product.rating} / 5</b>
            </div>
            <div className="story-fact">
              <span>عدد المقيّمين</span>
              <b>{product.reviews}</b>
            </div>
            <div className="story-fact">
              <span>الكمية المتبقية</span>
              <b>{product.stock} قطعة</b>
            </div>
            {saved > 0 ? (
              <div className="story-fact">
                <span>توفيرك</span>
                <b className="is-save">
                  <Money sar={saved} />
                </b>
              </div>
            ) : null}
          </div>

          <p className="story-foot">«{name}» {tr2(language, "by Atyab Al-Jasem — hand-filled and wrapped in Riyadh.", "من إنتاج أطياب الجاسم — يُعبَّأ ويُغلَّف يدوياً في الرياض.")}</p>
        </div>
      </div>
    </div>
  );
}
