/* ============================================================
   أطياب الجاسم (React) — شريحة المفضلة (wishlistSlice)
   تُخزَّن كأرقام منتجات في localStorage بالمفتاح atyab-wishlist،
   ويُحفظ الترتيب كما اختاره العميل (الأحدث في الأعلى).
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { KEYS, readJSON } from "../persist.js";
import { authFetch } from "../../api/auth.js";
import { ENDPOINTS } from "../api.js";

function readIds() {
  const arr = readJSON(KEYS.wishlist, []);
  if (!Array.isArray(arr)) return [];
  const out = [];
  arr.forEach(function (n) {
    const id = Number(n);
    if (id && out.indexOf(id) === -1) out.push(id);
  });
  return out;
}

const slice = createSlice({
  name: "wishlist",
  initialState: { ids: readIds() },
  reducers: {
    toggle: function (state, action) {
      const id = Number(action.payload);
      if (!id) return;
      const at = state.ids.indexOf(id);
      if (at === -1) state.ids.unshift(id);
      else state.ids.splice(at, 1);
    },
    add: function (state, action) {
      const id = Number(action.payload);
      if (id && state.ids.indexOf(id) === -1) state.ids.unshift(id);
    },
    remove: function (state, action) {
      const id = Number(action.payload);
      state.ids = state.ids.filter(function (n) {
        return n !== id;
      });
    },
    clear: function (state) {
      state.ids = [];
    },
    /* ★ استبدال كامل من مفضلة الخادم (بعد سحب + دمج) */
    wishesReplaced: function (state, action) {
      const list = Array.isArray(action.payload) ? action.payload : [];
      const out = [];
      list.forEach(function (n) {
        const id = Number(n);
        if (id && out.indexOf(id) === -1) out.push(id);
      });
      state.ids = out;
    }
  }
});

export const wishlistActions = slice.actions;
export const wishlistReducer = slice.reducer;
export const selectWishlistIds = function (state) {
  return state.wishlist.ids;
};
export const selectWishlistCount = function (state) {
  return state.wishlist.ids.length;
};

/* ============================================================
   مزامنة المفضلة مع الخادم (للأعضاء فقط — الضيف محلي خالص)
   نفس فلسفة السلة: سحب + اتحاد عند الدخول، ومرآة فورية بعدها.
   ============================================================ */

function serverCustomerId(getState) {
  try {
    const s = getState();
    return Number(s.user && s.user.auth && s.user.auth.customerId) || 0;
  } catch (e) {
    return 0;
  }
}

let wishChain = Promise.resolve();
function queueWish(fn) {
  wishChain = wishChain.then(fn, fn);
}

async function readJsonSafe(res) {
  try {
    const t = await res.text();
    return t ? JSON.parse(t) : null;
  } catch (e) {
    return null;
  }
}

function wishIdsOf(payload) {
  let list = null;
  if (Array.isArray(payload)) list = payload;
  else if (payload && Array.isArray(payload.items)) list = payload.items;
  else if (payload && Array.isArray(payload.data)) list = payload.data;
  else if (payload && Array.isArray(payload.wishlist)) list = payload.wishlist;
  if (!list) return [];
  const out = [];
  list.forEach(function (o) {
    const v = o != null && typeof o === "object" ? o.productId != null ? o.productId : o.id : o;
    const id = Number(v);
    if (id && out.indexOf(id) === -1) out.push(id);
  });
  return out;
}

/* سحب + اتحاد + دفع الناقص — تُستدعى عند كل دخول */
export function pullWishlist() {
  return function (dispatch, getState) {
    const cid = serverCustomerId(getState);
    if (!cid) return Promise.resolve();
    return new Promise(function (done) {
      queueWish(async function () {
        try {
          const res = await authFetch(ENDPOINTS.wishOf(cid), { method: "GET" });
          if (res.status === 403 || res.status === 401) return done();
          if (res.status !== 404 && !res.ok) return done();
          const serverIds = res.status === 404 ? [] : wishIdsOf(await readJsonSafe(res));
          const local = (getState().wishlist.ids || []).slice();
          const union = local.slice();
          serverIds.forEach(function (id) {
            if (union.indexOf(id) === -1) union.push(id);
          });
          const missing = local.filter(function (id) {
            return serverIds.indexOf(id) === -1;
          });
          for (let i = 0; i < missing.length; i++) {
            try {
              await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: missing[i] } });
            } catch (e) {}
          }
          dispatch(wishlistActions.wishesReplaced(union));
        } catch (e) {} finally {
          done();
        }
      });
    });
  };
}

/* تبديل مع مرآة فورية للخادم */
export function toggleWish(id) {
  return function (dispatch, getState) {
    const num = Number(id);
    if (!num) return;
    dispatch(wishlistActions.toggle(num));
    const cid = serverCustomerId(getState);
    if (!cid) return;
    const on = getState().wishlist.ids.indexOf(num) !== -1;
    queueWish(async function () {
      try {
        if (on) await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: num } });
        else await authFetch(ENDPOINTS.wishRemove(cid, num), { method: "DELETE" });
      } catch (e) {}
    });
  };
}

/* حذف صريح مع مرآة فورية للخادم */
export function removeWish(id) {
  return function (dispatch, getState) {
    const num = Number(id);
    if (!num) return;
    dispatch(wishlistActions.remove(num));
    const cid = serverCustomerId(getState);
    if (!cid) return;
    queueWish(async function () {
      try {
        await authFetch(ENDPOINTS.wishRemove(cid, num), { method: "DELETE" });
      } catch (e) {}
    });
  };
}
