import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import {
  getCustomer, updateCustomer, addCustomerProfile,
  getLocations, addLocation, updateLocation, ensureLocationIds, toLocationBody
} from "../../api/customers.js";
import { isNewCustomerProfile } from "../../validation.js";

export const fetchCustomerData = createAsyncThunk(
  "customer/fetchAll",
  async function (customerId) {
    const id = Number(customerId);
    if (!id) throw new Error("no customer");
    const details = await getCustomer(id).catch(function (e) {
      if (e && e.status === 404) return null;
      throw e;
    });
    const locations = await getLocations(id).catch(function () { return []; });
    return { details: details, locations: locations || [], customerId: id };
  }
);

function isFirstProfile(details) {
  return isNewCustomerProfile(details);
}

export const saveProfileSmart = createAsyncThunk(
  "customer/saveProfile",
  async function (input, thunk) {
    const id = Number(input && input.customerId);
    if (!id) throw new Error("no customer");
    const body = {
      firstName: String(input.firstName || ""),
      lastName: String(input.lastName || ""),
      phoneNumber: String(input.phoneNumber || "")
    };
    const state = thunk.getState();
    const known = state.customer && state.customer.details;
    let mode = isFirstProfile(known) ? "add" : "update";
    if (input.prefer) mode = input.prefer;
    try {
      const out = mode === "add"
        ? await addCustomerProfile(id, body)
        : await updateCustomer(id, body);
      return { mode: mode, saved: out || body };
    } catch (e) {
      if (mode === "add" && e && (e.status === 409 || e.status === 400)) {
        const out = await updateCustomer(id, body);
        return { mode: "update", saved: out || body };
      }
      if (mode === "update" && e && e.status === 404) {
        const out = await addCustomerProfile(id, body);
        return { mode: "add", saved: out || body };
      }
      throw e;
    }
  }
);

export const saveLocationSmart = createAsyncThunk(
  "customer/saveLocation",
  async function (input, thunk) {
    const id = Number(input && input.customerId);
    if (!id) throw new Error("no customer");
    const form = input.form || {};
    const ids = await ensureLocationIds(form.region, form.city);
    const body = toLocationBody({
      region: form.region,
      city: form.city,
      countryId: ids.countryId,
      cityId: ids.cityId,
      district: form.district != null ? form.district : form.area,
      street: form.street,
      building: form.building,
      postal: form.postal != null ? form.postal : form.zipCode,
      landmark: form.landmark != null ? form.landmark : form.nearTo,
      addressType: form.addressType || form.type || form.propertyType,
      notes: form.notes != null ? form.notes : form.deliveryNote,
      isDefault: form.isDefault
    });
    const state = thunk.getState();
    const list = (state.customer && state.customer.locations) || [];
    const wanted = input.locationId != null ? Number(input.locationId) : null;
    const existing = wanted != null
      ? list.filter(function (l) { return Number(l.locationId != null ? l.locationId : l.id) === wanted; })[0]
      : (list.filter(function (l) { return !!l.isDefault; })[0] || list[0] || null);
    if (existing && existing.locationId != null) {
      const out = await updateLocation(id, existing.locationId, body);
      return { mode: "update", saved: out || body, locationId: existing.locationId };
    }
    if (existing && existing.id != null && existing.locationId == null) {
      const out = await updateLocation(id, existing.id, body);
      return { mode: "update", saved: out || body, locationId: existing.id };
    }
    const out = await addLocation(id, body);
    const newId = out && (out.locationId != null ? out.locationId : out.id);
    return { mode: "add", saved: out || body, locationId: newId != null ? newId : null };
  }
);

const slice = createSlice({
  name: "customer",
  initialState: {
    details: null,
    locations: [],
    status: "idle",
    saving: false,
    error: "",
    loadedFor: null,
    lastProfileMode: "",
    lastLocationMode: ""
  },
  reducers: {
    customerCleared: function (state) {
      state.details = null;
      state.locations = [];
      state.status = "idle";
      state.error = "";
      state.loadedFor = null;
    }
  },
  extraReducers: function (builder) {
    builder
      .addCase(fetchCustomerData.pending, function (state) {
        state.status = "loading";
        state.error = "";
      })
      .addCase(fetchCustomerData.fulfilled, function (state, action) {
        state.status = "ready";
        state.details = action.payload.details;
        state.locations = action.payload.locations;
        state.loadedFor = action.payload.customerId;
      })
      .addCase(fetchCustomerData.rejected, function (state, action) {
        state.status = "error";
        state.error = (action.error && action.error.message) || "";
      })
      .addCase(saveProfileSmart.pending, function (state) {
        state.saving = true;
        state.error = "";
      })
      .addCase(saveProfileSmart.fulfilled, function (state, action) {
        state.saving = false;
        state.lastProfileMode = action.payload.mode;
        const prev = state.details || {};
        state.details = Object.assign({}, prev, {
          firstName: action.meta.arg.firstName,
          lastName: action.meta.arg.lastName,
          phoneNumber: action.meta.arg.phoneNumber,
          isProfileComplete: true
        });
      })
      .addCase(saveProfileSmart.rejected, function (state, action) {
        state.saving = false;
        state.error = (action.error && action.error.message) || "";
      })
      .addCase(saveLocationSmart.pending, function (state) {
        state.saving = true;
        state.error = "";
      })
      .addCase(saveLocationSmart.fulfilled, function (state, action) {
        state.saving = false;
        state.lastLocationMode = action.payload.mode;
        const f = action.meta.arg.form || {};
        const lid = action.payload.locationId;
        const row = {
          area: f.district != null ? f.district : f.area,
          street: f.street || "",
          buildingName: f.building || "",
          zipCode: f.postal != null ? f.postal : f.zipCode || "",
          deliveryNote: f.notes || "",
          isDefault: f.isDefault == null ? true : !!f.isDefault
        };
        if (lid != null) row.locationId = lid;
        if (action.payload.mode === "update" && lid != null) {
          state.locations = state.locations.map(function (l) {
            const cur = l.locationId != null ? l.locationId : l.id;
            return Number(cur) === Number(lid) ? Object.assign({}, l, row) : l;
          });
        } else {
          state.locations = state.locations.concat([row]);
        }
      })
      .addCase(saveLocationSmart.rejected, function (state, action) {
        state.saving = false;
        state.error = (action.error && action.error.message) || "";
      });
  }
});

export const customerActions = slice.actions;
export const customerReducer = slice.reducer;

export const selectCustomerDetails = function (s) { return s.customer.details; };
export const selectCustomerLocations = function (s) { return s.customer.locations || []; };
export const selectHasServerAddress = function (s) { return (s.customer.locations || []).length > 0; };
export const selectDefaultLocation = function (s) {
  const list = s.customer.locations || [];
  return list.filter(function (l) { return !!l.isDefault; })[0] || list[0] || null;
};
export const selectIsProfileComplete = function (s) {
  const d = s.customer.details;
  if (!d) return false;
  if (typeof d.isProfileComplete === "boolean") return d.isProfileComplete;
  return !!(d.firstName && d.phoneNumber);
};
