/* ============================================================
   أطياب الجاسم (React) — شريحة العروض (offersSlice)

   تجلب العروض من الخادم الحي — مصدر واحد لصفحة العروض:
     GET  <API_BASE_URL>/api/offers/all

   الحالات (تُعرض في الصفحة: تحميل ← سكيلتون، فشل ← رسالة + إعادة):
     idle      لم تُطلب بعد
     loading   جارٍ الجلب
     succeeded وصلت البيانات (قد تكون فارغة)
     failed    فشل الجلب

   ★ التطبيع يقبل مفاتيح camelCase وPascalCase معاً — فأي شكل
     يرجعه السيرفر يُفهم. المزايا perks قد تصل مصفوفة أو نصاً
     (يُقسَّم بالسطر) — والصفحة تأخذ المصفوفة الجاهزة.
   ============================================================ */

import { createSlice, createAsyncThunk, createSelector } from "@reduxjs/toolkit";
import { api, apiUrl, ENDPOINTS, atyabLog } from "../api.js";

function get(raw, names, fallback) {
  const r = raw || {};
  for (let i = 0; i < names.length; i++) {
    if (r[names[i]] != null) return r[names[i]];
  }
  return fallback;
}

function asArray(v) {
  if (Array.isArray(v)) return v.filter(function (x) { return String(x == null ? "" : x).trim() !== ""; });
  const s = String(v == null ? "" : v).trim();
  if (!s) return [];
  try {
    const j = JSON.parse(s);
    if (Array.isArray(j)) return j;
  } catch (e) {}
  return s.split(/\r?\n|؛|;/).map(function (x) { return x.trim(); }).filter(Boolean);
}

function num(v, fallback) {
  const n = Number(v);
  return isNaN(n) ? fallback : n;
}

export function normalizeOfferItem(raw) {
  const r = raw || {};
  const id = num(get(r, ["productId", "ProductId", "id", "Id"], 0), 0);
  const price = num(get(r, ["price", "Price", "productPrice", "ProductPrice"], 0), 0);
  const final = num(get(r, ["finalPrice", "FinalPrice", "productFinalPrice", "ProductFinalPrice"], 0), 0) || price;
  return {
    id: id,
    nameAr: String(get(r, ["nameAr", "NameAr", "productNameAr", "ProductNameAr"], "") || ""),
    nameEn: String(get(r, ["nameEn", "NameEn", "productNameEn", "ProductNameEn"], "") || ""),
    titleAr: String(get(r, ["titleAr", "TitleAr", "productTitleAr", "ProductTitleAr"], "") || ""),
    titleEn: String(get(r, ["titleEn", "TitleEn", "productTitleEn", "ProductTitleEn"], "") || ""),
    price: price,
    finalPrice: final,
    typeId: num(get(r, ["typeId", "TypeId", "productTypeId", "ProductTypeId"], 0), 0),
    descAr: String(get(r, ["descriptionAr", "DescriptionAr"], "") || ""),
    descEn: String(get(r, ["descriptionEn", "DescriptionEn"], "") || ""),
    storyAr: String(get(r, ["storyAr", "StoryAr"], "") || ""),
    storyEn: String(get(r, ["storyEn", "StoryEn"], "") || ""),
    mainImageUrl: String(get(r, ["mainImageUrl", "MainImageUrl", "imageUrl", "ImageUrl"], "") || "")
  };
}

export function normalizeOffer(raw) {
  const r = raw || {};
  const id = num(get(r, ["offerId", "OfferId", "id", "Id"], 0), 0);
  const before = num(get(r, ["priceBefore", "PriceBefore"], 0), 0);
  const final = num(get(r, ["finalPrice", "FinalPrice"], 0), 0);
  const items = get(r, ["items", "Items"], []);
  /* ★ معرّف الباقة في السلة: وحدة واحدة تُباع وتُحاسَب كاملة (9000000 + id) */
  const bundleId = id ? 9000000 + id : 0;
  return {
    id: id,
    bundleId: bundleId,
    key: String(get(r, ["offerCode", "OfferCode"], "") || id || "offer"),
    code: String(get(r, ["offerCode", "OfferCode"], "") || ""),
    name: String(get(r, ["offerName", "OfferName"], "") || ""),
    nameAr: String(get(r, ["offerNameAr", "OfferNameAr"], get(r, ["offerName", "OfferName"], "")) || ""),
    nameEn: String(get(r, ["offerNameEn", "OfferNameEn"], get(r, ["offerName", "OfferName"], "")) || ""),
    taglineAr: String(get(r, ["taglineAr", "TaglineAr"], "") || ""),
    taglineEn: String(get(r, ["taglineEn", "TaglineEn"], "") || ""),
    storyAr: String(get(r, ["storyAr", "StoryAr"], "") || ""),
    storyEn: String(get(r, ["storyEn", "StoryEn"], "") || ""),
    occasionAr: String(get(r, ["occasionAr", "OccasionAr"], "") || ""),
    occasionEn: String(get(r, ["occasionEn", "OccasionEn"], "") || ""),
    dateLabelAr: String(get(r, ["dateLabelAr", "DateLabelAr"], "") || ""),
    dateLabelEn: String(get(r, ["dateLabelEn", "DateLabelEn"], "") || ""),
    perksAr: asArray(get(r, ["perksAr", "PerksAr"], [])),
    perksEn: asArray(get(r, ["perksEn", "PerksEn"], [])),
    priceBefore: before,
    discountType: String(get(r, ["discountType", "DiscountType"], "") || ""),
    discountValue: num(get(r, ["discountValue", "DiscountValue"], 0), 0),
    finalPrice: final || before,
    startsAt: get(r, ["startsAt", "StartsAt"], "") || "",
    expiresAt: get(r, ["expiresAt", "ExpiresAt"], "") || "",
    isRunning: get(r, ["isRunning", "IsRunning"], true) !== false,
    usageLimit: num(get(r, ["usageLimit", "UsageLimit"], 0), 0),
    usagePerCustomer: num(get(r, ["usagePerCustomer", "UsagePerCustomer"], 0), 0),
    usedCount: num(get(r, ["usedCount", "UsedCount"], 0), 0),
    accent: String(get(r, ["accentColor", "AccentColor"], "") || "") || "#157347",
    accent2: String(get(r, ["accentColor2", "AccentColor2"], "") || "") || "#e6c470",
    motif: String(get(r, ["motif", "Motif"], "") || ""),
    stockLeft: num(get(r, ["stockLeft", "StockLeft"], 0), 0),
    soldToday: num(get(r, ["soldToday", "SoldToday"], 0), 0),
    totalStock: num(get(r, ["totalStock", "TotalStock"], 0), 0),
    isActive: get(r, ["isActive", "IsActive"], true) !== false,
    sortOrder: num(get(r, ["sortOrder", "SortOrder"], 0), 0),
    mainImageUrl: String(get(r, ["mainImageUrl", "MainImageUrl"], "") || ""),
    items: Array.isArray(items) ? items.map(normalizeOfferItem).filter(function (it) { return it.id; }) : []
  };
}

export const getOffers = createAsyncThunk(
  "offers/get",
  async function (_, { rejectWithValue }) {
    try {
      atyabLog("offers FETCH");
      const res = await api.get(apiUrl(ENDPOINTS.offersAll));
      const list = Array.isArray(res.data) ? res.data : [];
      atyabLog("offers CACHED", list.length);
      return list.map(normalizeOffer);
    } catch (err) {
      atyabLog("offers FAIL");
      return rejectWithValue("تعذّر جلب العروض");
    }
  },
  {
    condition: function (force, { getState }) {
      const s = getState().offers;
      if (!s) return true;
      if (s.status === "loading") { atyabLog("offers IN-FLIGHT"); return false; }
      if (force === true) { atyabLog("offers FORCE"); return true; }
      if (s.status === "succeeded" && Date.now() - (s.lastFetchedAt || 0) < 120000) { atyabLog("offers CACHE-HIT"); return false; }
      atyabLog("offers MISS");
      return true;
    }
  }
);

const slice = createSlice({
  name: "offers",
  initialState: { items: [], status: "idle", error: "", lastFetchedAt: 0 },
  reducers: {},
  extraReducers: function (builder) {
    builder
      .addCase(getOffers.pending, function (state) {
        state.status = "loading";
        state.error = "";
      })
      .addCase(getOffers.fulfilled, function (state, action) {
        state.status = "succeeded";
        state.items = Array.isArray(action.payload) ? action.payload : [];
        state.lastFetchedAt = Date.now();
      })
      .addCase(getOffers.rejected, function (state, action) {
        state.status = "failed";
        state.error = action.payload || "fail";
      });
  }
});

export const offersReducer = slice.reducer;

export function selectOffersList(state) {
  return (state.offers && state.offers.items) || [];
}

export function selectOffersStatus(state) {
  return (state.offers && state.offers.status) || "idle";
}

export function selectOffersError(state) {
  return (state.offers && state.offers.error) || "";
}

/* ★ خريطة منتج → عرضه الساري: { [productId]: { offerId, name, expiresAt } }
   تُغذي شارة «باقة» والعدّاد المصغّر على بطاقات المنتجات. */
export const selectOfferMap = createSelector([selectOffersList], function (list) {
  const map = {};
  const now = Date.now();
  (list || []).forEach(function (o) {
    if (!o || o.isActive === false || o.isRunning === false) return;
    const end = Date.parse(o.expiresAt) || 0;
    if (end && end <= now) return;
    (o.items || []).forEach(function (it) {
      const id = Number(it.id);
      if (!id || map[id]) return;
      map[id] = { offerId: o.id, name: o.nameAr || o.nameEn || o.name, expiresAt: o.expiresAt || "" };
    });
  });
  return map;
});
