/* ============================================================
   أطياب الجاسم (React) — صفحة العودة من الدفع (PaymentReturnPage)

   العقد الوحيد (FRONTEND_CONTRACT §10):
     PayTabs يعيد المتصفح بـ ?cartId=AY-5-...
     ★ الحُكم من: GET /api/payments/{id}/status?cartId=
       → { status, orderId, invoiceNumber, grandTotal, tranRef } —
       تُستطلع كل ~3 ثوانٍ حتى ~60 ثانية («جارٍ التأكيد…» أثناء الانتظار).
     ★ 409 بعد الدفع تعني غالباً أن الـcallback سوّاها —
       يُعاد قراءة تفاصيل الطلب بدل الفشل.
   ★ النجاح: علامة ✓ كبيرة + الفاتورة + أزرار (طلباتي/متابعة التسوق).
   ★ الفشل: شاشة خطأ واضحة (أعد المحاولة لاحقاً أو كلم الدعم) + أزرار
     (المحاولة مجدداً/العربة/العودة للمتجر) — لا توجيه تلقائي أبداً.
   ★ مُتقاعَد ممنوع: attempts/{merchantReference} — دفعة قديمة بلا cartId
     تُوجَّه لصفحة «راجع طلباتي» بدل الاستعلام الميت.
   ============================================================ */

import { useEffect, useRef, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { PATHS } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { T, tr2 } from "../i18n.js";
import { Icon } from "../components/Source/Icons.jsx";
import { Invoice } from "./CheckoutPage.jsx";
import { cartActions, clearServerBasket } from "../redux/slices/cartSlice.js";
import { ordersActions } from "../redux/slices/ordersSlice.js";
import { currencyMeta } from "../redux/selectors.js";
import { methodLabelOf } from "../redux/slices/ordersSlice.js";
import { kindOf } from "../constants/payment.js";
import { fetchServerOrderDetail, normalizeServerOrder } from "../api/orders.js";
import {
  getPaymentStatus,
  readPendingPayment,
  clearPendingPayment
} from "../api/payments.js";

const POLL_EVERY_MS = 3000;
const POLL_MAX = 20;

function normStatus(v) {
  const s = String(v == null ? "" : v).trim().toLowerCase();
  if (!s) return "pending";
  if (s === "a" || s === "success" || s === "succeeded" || s === "succeed" || s === "authorised" || s === "authorized" || s === "captured" || s === "paid" || s === "settled" || s === "settle" || s === "approved" || s === "complete" || s === "completed") return "success";
  if (s === "fail" || s === "failed" || s === "failure" || s === "declined" || s === "cancelled" || s === "canceled" || s === "cancel" || s === "void" || s === "refunded" || s === "rejected" || s === "error" || s === "d" || s === "c") return "fail";
  return "pending";
}

function attemptOrderId(st, pending) {
  const c = [st && st.orderId, st && st.order_id, st && st.orderID, st && st.data && st.data.orderId, pending && pending.orderId].filter(Boolean)[0];
  return Number(c) || 0;
}

export default function PaymentReturnPage() {
  usePageMeta({ route: "paymentReturn", titleAr: "نتيجة الدفع", titleEn: "Payment result" });

  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  const profileCurrency = useAppSelector(function (s) {
    return (s.user && s.user.profile && s.user.profile.currency) || "AED";
  });

  const [params] = useSearchParams();
  const [phase, setPhase] = useState("checking");
  const [order, setOrder] = useState(null);
  const [note, setNote] = useState("");
  const tries = useRef(0);

  const pending = readPendingPayment();
  /* ★ cartId هو المرجع الوحيد (§10) — من رابط العودة أو الدفعة المعلّقة */
  const cartId =
    params.get("cartId") ||
    params.get("cart_id") ||
    (pending && (pending.cartId || pending.cart_id)) ||
    "";
  /* ★ مرجع قديم (merchantReference) من دفعات ما قبل العقد — لا استعلام له
     (attempts مُتقاعَدة) — يُوجَّه صاحبه لصفحة «راجع طلباتي» */
  const legacyRef =
    params.get("merchantReference") ||
    params.get("merchant_reference") ||
    params.get("merchantRef") ||
    params.get("reference") ||
    params.get("ref") ||
    (pending && (pending.merchantReference || pending.merchant_reference || pending.reference)) ||
    "";
  const hasRef = !!cartId;
  const legacyOnly = !cartId && !!legacyRef;

  useEffect(
    function () {
      if (!customerId || !hasRef) return;
      let alive = true;
      let timer = 0;

      function fail(msg) {
        if (!alive) return;
        setPhase("failed");
        setNote(msg || "");
      }

      function succeed(status, detail) {
        if (!alive) return;
        const meta = currencyMeta(profileCurrency);
        const pend = readPendingPayment() || {};
        const built = normalizeServerOrder(detail, {
          method: pend.method || "",
          methodLabel: methodLabelOf(pend.method, language) || String(status.paymentMethod || status.payment_method || ""),
          kind: kindOf(pend.method),
          customer: pend.customer || {},
          currency: { key: meta.key, rate: meta.rate, decimals: meta.decimals, symbol: meta.symbol, symbolEn: meta.symbolEn, position: meta.position }
        });
        dispatch(ordersActions.orderPlaced(built));
        dispatch(cartActions.clearCart());
        try {
          clearServerBasket(Number(customerId));
        } catch (e) {}
        clearPendingPayment();
        setOrder(built);
        setPhase("paid");
        try {
          window.scrollTo(0, 0);
        } catch (e) {}
      }

      function queryStatus() {
        return getPaymentStatus(Number(customerId), String(cartId));
      }

      /* ★ 409 بعد الدفع = الـcallback سوّاها غالباً (§10) —
         نعيد قراءة تفاصيل الطلب بدل الفشل */
      function settleFromOrderFallback() {
        const pend = readPendingPayment() || {};
        const oid = Number(pend.orderId) || 0;
        if (!oid) return false;
        fetchServerOrderDetail(Number(customerId), oid).then(
          function (detail) {
            if (!alive) return;
            const paid = String((detail && (detail.paymentStatus || detail.payment_status)) || "").toLowerCase();
            if (paid.indexOf("paid") !== -1 || paid.indexOf("success") !== -1 || paid.indexOf("مدفوع") !== -1 || paid.indexOf("مقبول") !== -1 || paid.indexOf("ناجح") !== -1) {
              succeed({ paymentMethod: detail.paymentMethod }, detail);
            } else {
              fail("سُجّل طلبك بانتظار تأكيد الدفع — ستجده محدّثاً في «طلباتي» تلقائياً.");
            }
          },
          function () {
            if (!alive) return;
            fail("تعذّر التأكد من الدفع الآن — راجع «طلباتي» بعد قليل، وإن خُصم المبلغ سيظهر مدفوعاً.");
          }
        );
        return true;
      }

      function check() {
        tries.current += 1;
        queryStatus().then(
          function (st) {
            if (!alive) return;
            const raw = (st && (st.status || st.state || st.paymentStatus || st.result)) || "";
            const s = normStatus(raw);
            if (s === "success") {
              const oid = attemptOrderId(st, pending);
              if (!oid) {
                fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي».");
                return;
              }
              fetchServerOrderDetail(Number(customerId), Number(oid)).then(
                function (detail) {
                  succeed(st, detail);
                },
                function () {
                  fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي».");
                }
              );
              return;
            }
            if (s === "fail") {
              fail("");
              return;
            }
            if (tries.current >= POLL_MAX) {
              setPhase("waiting");
              return;
            }
            timer = window.setTimeout(check, POLL_EVERY_MS);
          },
          function (err) {
            if (!alive) return;
            if (err && (err.status === 404 || err.status === 501)) {
              setPhase("unready");
              return;
            }
            /* ★ 409 = غالباً تسوية الـcallback — أعد قراءة الطلب */
            if (err && err.status === 409) {
              if (settleFromOrderFallback()) return;
            }
            if (tries.current >= POLL_MAX) {
              setPhase("waiting");
              return;
            }
            timer = window.setTimeout(check, POLL_EVERY_MS);
          }
        );
      }

      check();
      return function () {
        alive = false;
        if (timer) window.clearTimeout(timer);
      };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [customerId, cartId]
  );

  /* ---------- بلا جلسة ---------- */
  if (!customerId) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="user" strokeWidth={1.6} />
          </span>
          <h3>سجّل الدخول لعرض نتيجة الدفع</h3>
          <p>انتهت الجلسة أثناء الدفع — سجّل الدخول وستجد طلبك في «طلباتي».</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.login}>
              تسجيل الدخول
            </Link>
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- بلا مرجع دفع ---------- */
  if (!hasRef) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          <h3>{legacyOnly ? "راجع حالة طلبك في «طلباتي»" : "لا توجد عملية دفع هنا"}</h3>
          <p>
            {legacyOnly
              ? "عملية الدفع هذه من نسخة قديمة بلا رقم سلة — لا يمكن الاستعلام عنها مباشرة، لكن طلبك محفوظ وستجد حالته (مدفوع/بانتظار الدفع) في «طلباتي»."
              : "لم نجد رقم سلة للدفع (cartId) — أكمل طلبك من العربة وستُحوَّل لصفحة الدفع الآمنة."}
          </p>
          <div className="wl-empty-actions">
            {legacyOnly ? (
              <Link className="btn-primary" to={PATHS.profile}>
                طلباتي
              </Link>
            ) : (
              <Link className="btn-primary" to={PATHS.cart}>
                العربة
              </Link>
            )}
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- ناجح: الفاتورة ---------- */
  if (phase === "paid" && order) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <header className="ck-done-head">
          <span className="ck-done-ic">
            <Icon name="check" strokeWidth={2.6} />
          </span>
          <span className="eyebrow">تم الدفع</span>
          <h1>
            شكراً لك — <span className="gold-text">دُفع طلبك بنجاح</span>
          </h1>
          <p className="ck-done-sub">
            استلمنا مبلغ فاتورتك برقم <b>#{order.invoiceNo}</b>، وأفرغنا العربة.
          </p>
        </header>

        <div className="ck-done-actions">
          <Link className="btn-ghost" to={PATHS.profile}>
            <Icon name="doc" strokeWidth={1.8} />
            <span>طلباتي</span>
          </Link>
          <Link className="btn-ghost" to={PATHS.perfumes}>
            <Icon name="cart" strokeWidth={1.8} />
            <span>متابعة التسوق</span>
          </Link>
        </div>

        <Invoice order={order} language={language} />
      </section>
    );
  }

  /* ---------- فاشل/ملغي: صفحة خطأ واضحة — أعد المحاولة أو كلم الدعم ---------- */
  if (phase === "failed") {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="alert" strokeWidth={1.6} />
          </span>
          <h3>حدث خطأ ما</h3>
          <p>{note || tr2(language, "The payment did not complete — please try again later or contact support. Your cart is kept as is.", "لم تتم عملية الدفع — أعد المحاولة لاحقاً أو كلم الدعم. عربتك محفوظة كما هي.")}</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.checkout}>
              المحاولة مجدداً
            </Link>
            <Link className="btn-ghost" to={PATHS.cart}>
              العربة
            </Link>
            <Link className="btn-ghost" to={PATHS.perfumes}>
              العودة للمتجر
            </Link>
            <Link className="btn-ghost" to={PATHS.contact}>
              كلم الدعم
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- الخدمة غير جاهزة بعد ---------- */
  if (phase === "unready") {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="info" strokeWidth={1.6} />
          </span>
          <h3>الدفع الإلكتروني يُجهَّز الآن</h3>
          <p>طلبك محفوظ بانتظار الدفع — أكمله نقداً عند الاستلام أو عُد قريباً للدفع بالبطاقة.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.profile}>
              طلباتي
            </Link>
            <Link className="btn-ghost" to={PATHS.checkout}>
              إتمام الدفع
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- فحص/انتظار ---------- */
  return (
    <section className="container view ck ct" id="paymentReturnView">
      <div className="ct-empty">
        <span className="ct-empty-ic">
          <Icon name="lock" strokeWidth={1.6} />
        </span>
        <h3>{phase === "waiting" ? "الدفع قيد المراجعة" : "نتحقق من الدفع…"}</h3>
        <p>
          {phase === "waiting"
            ? "لم يصل التأكيد بعد — إن خُصم المبلغ سيظهر طلبك مدفوعاً في «طلباتي» تلقائياً."
            : "لحظات ونعرض النتيجة — لا تغلق الصفحة."}
        </p>
        <div className="wl-empty-actions">
          <Link className="btn-ghost" to={PATHS.profile}>
            طلباتي
          </Link>
        </div>
      </div>
    </section>
  );
}
