/* ------------------------------------------------------------
   3) ترجمة بيانات المنتجات — تُبنى من ملف البيانات نفسه
   (PERFUME_EN · INCENSE_EN) فلا تُكرَّر أي ترجمة هنا.
   ------------------------------------------------------------ */
function dataPhrases() {
  const map = {};
  const lists = [ATYAB_allProducts()];
  for (let l = 0; l < lists.length; l++) {
    const items = lists[l] || [];
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (p.name && p.nameEn) map[p.name] = p.nameEn;
      if (p.desc && p.descEn) map[p.desc] = p.descEn;
      if (p.story && p.storyEn) map[p.story] = p.storyEn;
      if (p.size && p.sizeEn) map[p.size] = p.sizeEn;
      if (p.kindLabel && p.kindLabelEn) map[p.kindLabel] = p.kindLabelEn;
      if (p.notes && p.notesEn) {
        const a = p.notes;
        const b = p.notesEn;
        if (a.top && b.top) map[a.top] = b.top;
        if (a.heart && b.heart) map[a.heart] = b.heart;
        if (a.base && b.base) map[a.base] = b.base;
      }
    }
  }
  return map;
}

/* القاموس الذي يقرأه مترجم الواجهة (src/uiTranslate.js) */
export const PHRASES = Object.assign({}, UI_PHRASES, dataPhrases());

/* تحديث قاموس الواجهة من القوائم الحيّة بعد وصولها من الـ API.
   تُستدعى من مصنع الشرائح بعد كل جلب ناجح — فمترجم الواجهة يعيد
   بناء تعبيره تلقائياً عند تغيّر عدد المفاتيح. */
export function refreshPhrases(list) {
  const items = Array.isArray(list) ? list : ATYAB_allProducts() || [];
  let added = 0;
  function put(ar, en) {
    if (ar && en && ar !== en && PHRASES[ar] == null) {
      PHRASES[ar] = en;
      added++;
    }
  }
  for (let i = 0; i < items.length; i++) {
    const p = items[i];
    if (!p) continue;
    put(p.name, p.nameEn);
    put(p.desc, p.descEn);
    put(p.story, p.storyEn);
    put(p.size, p.sizeEn);
    put(p.kindLabel, p.kindLabelEn);
    if (p.notes && p.notesEn) {
      put(p.notes.top, p.notesEn.top);
      put(p.notes.heart, p.notesEn.heart);
      put(p.notes.base, p.notesEn.base);
    }
  }
  return added;
}

/* ------------------------------------------------------------
   دوال القراءة
   ------------------------------------------------------------ */

/* t(lang, key, fallback) — عربي هو الاحتياط دائماً */
export function t(lang, key, fallback) {
  if (lang === "en") return EN[key] != null ? EN[key] : fallback == null ? "" : fallback;
  return AR[key] != null ? AR[key] : fallback == null ? "" : fallback;
}

/* نصّ ثنائي اللغة: {ar, en} أو نصّ عربي يُترجَم من القاموس */
export function T(value, lang) {
  if (value == null) return "";
  if (typeof value === "string") {
    if (lang === "en" && PHRASES[value] != null) return PHRASES[value];
    return value;
  }
  if (lang === "en" && value.en) return value.en;
  return value.ar != null ? value.ar : value.en || "";
}

/* ---------- نصوص المنتج بلغة الواجهة ----------
   ★ مصدرها ملف البيانات (nameEn · descEn · storyEn …) — أي «عمود
     الترجمة» في سجلّ المنتج. استعملها في أي كود جديد يعرض منتجاً. */
export function productName(product, lang) {
  if (!product) return "";
  if (lang === "en") return product.nameEn || product.name || "";
  return product.name || product.nameEn || "";
}

export function productDesc(product, lang) {
  if (!product) return "";
  if (lang === "en") return product.descEn || product.desc || "";
  return product.desc || product.descEn || "";
}

export function productStory(product, lang) {
  if (!product) return "";
  const base = product.story || product.desc || "";
  if (lang === "en") return product.storyEn || product.descEn || base;
  return base || product.storyEn;
}

export function productSize(product, lang) {
  if (!product) return "";
  if (lang === "en") return product.sizeEn || product.size || "";
  return product.size || product.sizeEn || "";
}

export function productKind(product, lang) {
  if (!product) return "";
  if (lang === "en") return product.kindLabelEn || product.kindLabel || genderLabelOf(product.gender, "en");
  return product.kindLabel || product.kindLabelEn || genderLabelOf(product.gender, "ar");
}

export function productNotes(product, lang) {
  if (!product) return { top: "", heart: "", base: "" };
  const ar = product.notes || { top: "", heart: "", base: "" };
  if (lang !== "en") return ar;
  const en = product.notesEn;
  if (!en) return ar;
  return { top: en.top || ar.top, heart: en.heart || ar.heart, base: en.base || ar.base };
}

/* تسمية الجنس بلغة الواجهة — تُبنى عند العرض لا في الشريحة */
export function genderLabelOf(gender, lang) {
  const g = String(gender || "").trim().toLowerCase();
  if (lang === "en") {
    if (g === "men") return "For men";
    if (g === "women") return "For women";
    return "For everyone";
  }
  if (g === "men") return "مناسب للرجال";
  if (g === "women") return "مناسب للنساء";
  return "مناسب للجنسين";
}

/* نصّ ثنائي اللغة سريع في مكان الاستعمال: tr2(lang, en, ar) */
export function tr2(lang, en, ar) {
  return lang === "en" ? en : ar;
}

/* جنس المنتج بلغة الواجهة («بخور» / «عطر» ⟷ bakhoor / perfume) */
export function nounOf(product, lang) {
  const isBakhoor = !!(product && (product.kindLabel || (product.kind && product.kind !== "perfume")));
  if (lang === "en") return isBakhoor ? "bakhoor" : "perfume";
  return isBakhoor ? "بخور" : "عطر";
}

/* عدد المنتجات بصيغة صحيحة بلغة الواجهة: «5 عطور» ⟷ «5 perfumes» */
export function countOfNoun(count, noun, lang) {
  if (lang === "en") return count + " " + noun + (Number(count) === 1 ? "" : "s");
  return count + " " + noun;
}

/* جمع عربي صحيح: 1 → «عطر واحد» · 2 → «عطران» · 3-10 → «عطور» · 11+ → «عطراً» */
export function pluralAr(count, forms) {
  if (!forms) return String(count);
  if (count === 1) return forms.one;
  if (count === 2) return forms.two;
  if (count >= 3 && count <= 10) return forms.few;
  return forms.many;
}

/* عدّ النتائج بالعربية الصحيحة — كما في صفحة البحث القديمة
   ★ بالإنجليزية: "1 result" / "5 results" / "No results" */
export function countLabel(count, lang) {
  if (lang === "en") {
    if (count === 0) return "No results";
    return count + (count === 1 ? " result" : " results");
  }
  if (count === 0) return "لا نتائج";
  if (count === 1) return "نتيجة واحدة";
  if (count === 2) return "نتيجتان";
  if (count <= 10) return count + " نتائج";
  return count + " نتيجة";
}

export function isEn(lang) {
  return lang === "en";
}

export function dirOf(lang) {
  return lang === "en" ? "ltr" : "rtl";
}
